def verify_trust_proof(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """验证未在本租户保存的外部谓词证明，返回 (是否有效, 失败原因)。

    请求体须恰含 proof（对象）、challenge（非空字符串）与
    source_tenant_id（非空字符串）。proof 须恰为 prove 响应九字段：
    proof_id、credential_id、issuer_did（非空字符串）、
    issuer_key_version（非布尔正整数）、predicates、results、
    challenge/expires_at/proof（非空字符串）。results 与 predicates
    等长且仅含布尔；请求 challenge 须等于证明对象 challenge。
    predicates 项须恰含 path、op 及可选 value；op 限
    exists/eq/gte/lte，exists 禁 value，其余必填 value，gte/lte 的
    value 为非布尔数字；path 须以 / 开头、RFC6901 转义合法且无重复
    或祖先重叠（不校验 claims 命中、数组路径或命中值类型，也不重算
    results）。

    校验顺序：请求 -> 证明字段与挑战 -> 锚点 -> 签名格式 ->
    ES256 验签（覆盖除 proof 外八字段并加入
    tenant_id=source_tenant_id 的规范化 JSON）-> 期限。锚点按当前
    租户 (issuer_did, issuer_key_version) 查找，仅 active 的 P-256
    公钥可用。expires_at 须为 UTC 秒精度 Z 格式，到期返回
    “证明已过期”。原验真成功后按当前租户查 issuer_did 外部停用
    通告，命中返回“外部签发DID已停用：<reason>”，仅他租户有通告
    不影响结论。只读：不消费、不登记任何资源、不写状态/历史/审计，
    绝不向上抛异常。
    """
    # 1. 请求结构：恰含 proof、challenge、source_tenant_id。
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象"
    request_fields = {"proof", "challenge", "source_tenant_id"}
    if set(data) != request_fields:
        missing = sorted(request_fields - set(data))
        if missing:
            return False, f"请求缺少字段: {', '.join(missing)}"
        extra = sorted(set(data) - request_fields)
        return False, f"请求含多余字段: {', '.join(extra)}"
    proof = data["proof"]
    request_challenge = data["challenge"]
    source_tenant_id = data["source_tenant_id"]
    if not isinstance(proof, dict):
        return False, "请求不合法: 字段 proof 必须为 JSON 对象"
    if not isinstance(request_challenge, str) or not request_challenge:
        return False, "请求不合法: 字段 challenge 必须为非空字符串"
    if not isinstance(source_tenant_id, str) or not source_tenant_id:
        return False, (
            "请求不合法: 字段 source_tenant_id 必须为非空字符串"
        )

    # 2. 证明字段与挑战。
    required_fields = {
        "proof_id",
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "predicates",
        "results",
        "challenge",
        "expires_at",
        "proof",
    }
    if set(proof) != required_fields:
        missing = sorted(required_fields - set(proof))
        if missing:
            return False, f"证明缺少字段: {', '.join(missing)}"
        extra = sorted(set(proof) - required_fields)
        return False, f"证明含多余字段: {', '.join(extra)}"
    for field in ("proof_id", "credential_id", "issuer_did"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"
    key_version = proof["issuer_key_version"]
    if (
        not isinstance(key_version, int)
        or isinstance(key_version, bool)
        or key_version < 1
    ):
        return False, "证明字段 issuer_key_version 必须为正整数"
    predicates = proof["predicates"]
    if not isinstance(predicates, list) or not predicates:
        return False, "证明字段 predicates 必须为非空数组"
    seen_tokens: List[Tuple[str, ...]] = []
    for item in predicates:
        if not isinstance(item, dict):
            return False, "证明 predicates 元素必须为 JSON 对象"
        if set(item) - {"path", "op", "value"}:
            extra = sorted(set(item) - {"path", "op", "value"})
            return False, (
                f"证明 predicates 元素含多余字段: {', '.join(extra)}"
            )
        if "path" not in item:
            return False, "证明 predicates 元素缺少字段: path"
        if "op" not in item:
            return False, "证明 predicates 元素缺少字段: op"
        op = item["op"]
        if op not in _PREDICATE_OPS:
            return False, (
                f"证明 predicates 元素 op 非法: {op!r}"
                "（仅支持 exists/eq/gte/lte）"
            )
        if op == "exists":
            if "value" in item:
                return False, (
                    "证明 predicates 元素 op 为 exists 时禁止 value 字段"
                )
        elif "value" not in item:
            return False, (
                f"证明 predicates 元素 op 为 {op} 时缺少字段: value"
            )
        elif op in ("gte", "lte") and not _is_number(item["value"]):
            return False, (
                f"证明 predicates 元素 op 为 {op} 时 value 必须为非布尔数字"
            )
        # 仅做指针语法与重叠校验：不查 claims 命中、不判数组路径。
        try:
            tokens = _parse_pointer(item["path"], "证明 predicates")
        except ValidationError as exc:
            return False, str(exc)
        if tokens in seen_tokens:
            return False, (
                f"证明 predicates 路径重复: {item['path']!r}"
            )
        for existing in seen_tokens:
            if tokens[: len(existing)] == existing:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"{item['path']!r} 被已选路径覆盖"
                )
            if existing[: len(tokens)] == tokens:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"已选路径被 {item['path']!r} 覆盖"
                )
        seen_tokens.append(tokens)
    results = proof["results"]
    if not isinstance(results, list) or len(results) != len(predicates):
        return False, (
            "证明字段 results 必须为与 predicates 等长的数组"
        )
    if any(not isinstance(item, bool) for item in results):
        return False, "证明字段 results 仅能包含布尔值"
    for field in ("challenge", "expires_at", "proof"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"
    if request_challenge != proof["challenge"]:
        return False, "挑战不匹配: 请求 challenge 与证明 challenge 不一致"

    # 3. 锚点：当前租户 (issuer_did, issuer_key_version)，仅 active。
    issuer_did = proof["issuer_did"]
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(key_version))
            if anchors is not None else None
        )
        public_pem = row.get("public_key", "") if row is not None else ""
        status = row.get("status", "active") if row is not None else None
        uses = row.get("uses") if row is not None else None
    if row is None:
        return False, f"锚点不存在: {issuer_did}#{key_version}"
    if status == "revoked":
        return False, f"锚点已吊销: {issuer_did}#{key_version}"
    # 用途白名单：active 锚点无 proof 用途时按锚点不可用处理
    if uses is not None and "proof" not in uses:
        return False, f"锚点不存在: {issuer_did}#{key_version}"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            f"锚点公钥不可用: {issuer_did}#{key_version} 不是合法 P-256 公钥"
        )

    # 4/5. 签名格式与密码学验签：覆盖除 proof 外八字段，并加入
    # tenant_id=source_tenant_id 后按规范化 JSON 验签。
    signature = proof["proof"]
    message = {k: v for k, v in proof.items() if k != "proof"}
    message["tenant_id"] = source_tenant_id
    try:
        crypto.verify(message, signature, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，证明内容或签名可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 6. 期限：expires_at 须为 UTC 秒精度 Z 格式；当前时间达到它即
    # 过期。只读，不消费、不写任何状态、不记审计。
    expires_value = proof["expires_at"]
    if not _UTC_Z_SHAPE_RE.match(expires_value):
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        expires_dt = _parse_utc_z(expires_value)
    except ValueError:
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    if datetime.now(timezone.utc) >= expires_dt:
        return False, "证明已过期"

    # 7. 原验真成功后、合并凭证状态前查本租户 issuer_did 外部停用
    #    通告：命中返回“外部签发DID已停用：<reason>”；无通告或仅他
    #    租户有通告维持原结论。只读，不写状态、不记审计。
    deactivation_reason = self._external_did_deactivation_reason(
        tenant_id, issuer_did, EXTERNAL_ISSUER_DID_DEACTIVATED_REASON_PREFIX
    )
    if deactivation_reason is not None:
        return False, deactivation_reason
    return True, ""

def verify_trust_proof_synced(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    proof: Any,
    challenge: Any,
    source_tenant_id: Any,
) -> Tuple[bool, str]:
    """以同步锚点验真外部谓词证明，返回 (是否有效, 失败原因)。

    请求结构（恰含 signer_did/at/proof/challenge/source_tenant_id
    及类型）由服务层校验（400）。本方法假定五键类型已合法：
    - 该签名方在本租户无同步检查点（含跨租户）抛 NotFoundError；
      at 超过检查点抛 ConflictError；
    - 证明九字段、predicates、results、challenge 与 expires_at
      规则沿用 :meth:`verify_trust_proof`；
    - 锚点取该来源 cursor<=at 的已同步事件，以 (issuer_did, 版本)
      最后事件为准；缺失、非 active 或 uses 无 proof 均返回
      (False, "同步锚点不可用")；
    - proof 须为 ES256、64 字节裸 R||S 无填充 base64url，覆盖除
      proof 外八字段并加入 tenant_id=source_tenant_id 的规范化
      JSON；格式错、验签错、到期依次返回 “签名格式错误”/
      “签名校验失败”/“证明已过期”，较早错误优先。

    校验顺序：请求 -> 证明字段 -> 挑战 -> 锚点 -> 签名格式 ->
    验签 -> 期限。纯只读：不改同步页、检查点、锚点、证明、状态或
    审计，结论随状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    return self._verify_synced_proof_against(
        latest, proof, challenge, source_tenant_id
    )

@staticmethod
def _verify_synced_proof_against(
    latest: Dict[Tuple[str, int], Dict[str, Any]],
    proof: Any,
    challenge: Any,
    source_tenant_id: Any,
) -> Tuple[bool, str]:
    """在已解析的同步锚点快照上验真一条外部谓词证明（只读）。

    假定 proof 为 JSON 对象、challenge 与 source_tenant_id 均为非空
    字符串；证明九字段、谓词/results、RFC6901 路径、挑战、锚点、
    签名覆盖（去掉 proof 后的八字段并加入
    tenant_id=source_tenant_id 的规范化 JSON）、签名格式、验签与
    期限规则及原因分类与 :meth:`verify_trust_proof_synced` 完全
    一致，供单条与批量同步锚点验真共用同一快照。
    """
    # 证明字段（沿用 /v1/trust/proofs/verify 的分类原因）：恰为
    # prove 响应九字段。
    required_fields = {
        "proof_id",
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "predicates",
        "results",

            return ROTATION_VERIFY_REASON_RECORD_DIGEST
        if any(
            not isinstance(digest_obj[field], str) for field in string_fields
        ):
            return ROTATION_VERIFY_REASON_RECORD_DIGEST
        prev = digest_obj.get("previous_proof_digest")
        if prev is not None and not isinstance(prev, str):
            return ROTATION_VERIFY_REASON_RECORD_DIGEST
        expected_digest = hashlib.sha256(
            crypto.canonicalize(digest_obj)
        ).hexdigest()
        if record.get("proof_digest") != expected_digest:
            return ROTATION_VERIFY_REASON_RECORD_DIGEST

    # 5/6. 旧钥/新钥签名：分别用记录内 from/to 公钥校验 from_proof/
    #     to_proof 对去掉三个 proof 字段记录的 ES256 签名。公钥 PEM
    #     解析、签名格式或密码学验签任一失败均计入对应签名失败。
    for idx in order:
        record = records[idx]
        signed_obj = _rotation_proof_object_fields(
            record, _ROTATION_PROOF_SIGNED_FIELDS
        )
        if signed_obj is None:
            return ROTATION_VERIFY_REASON_FROM_SIG
        try:
            crypto.verify(
                signed_obj,
                record["from_proof"],
                record["from_public_key"],
            )
        except Exception:  # noqa: BLE001 解析/格式/验签失败同因
            return ROTATION_VERIFY_REASON_FROM_SIG

    for idx in order:
        record = records[idx]
        signed_obj = _rotation_proof_object_fields(
            record, _ROTATION_PROOF_SIGNED_FIELDS
        )
        if signed_obj is None:
            return ROTATION_VERIFY_REASON_TO_SIG
        try:
            crypto.verify(
                signed_obj,
                record["to_proof"],
                record["to_public_key"],
            )
        except Exception:  # noqa: BLE001 解析/格式/验签失败同因
            return ROTATION_VERIFY_REASON_TO_SIG

    return None


def build_handler(store: VCStore) -> type:
    """构造绑定给定 store 的请求处理器类。"""

    class Handler(BaseHTTPRequestHandler):
        server_version = "VCBackend/0.1"

        # ------------------------------------------------------------ #
        # 响应工具
        # ------------------------------------------------------------ #
        def _send_json(self, status: int, payload: Any) -> None:
            body = _json_dumps(payload)
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_error(self, status: int, message: str) -> None:
            self._send_json(status, {"error": message})

        def _send_invalid(self, reason: str) -> None:
            """verify 端点统一失败响应：HTTP 200 + valid:false + 中文原因。"""
            self._send_json(200, {"valid": False, "reason": reason})

        def _tenant_id(self) -> str:
            """解析 X-Tenant-ID：缺省 default；显式空串 400。"""
            raw = self.headers.get("X-Tenant-ID")
            if raw is None:
                return DEFAULT_TENANT
            if raw == "":
                raise ValidationError("X-Tenant-ID 不能为空")
            return raw

        def _read_json(self) -> Dict[str, Any]:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            try:
                data = json.loads(raw.decode("utf-8")) if raw else None
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        def _read_optional_json(self) -> Dict[str, Any]:
            """读取可选请求体：空体等价于 {}，非空时须为 JSON 对象。"""
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            if not raw:
                return {}
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        # ------------------------------------------------------------ #
        # 路由
        # ------------------------------------------------------------ #
        def do_POST(self) -> None:  # noqa: N802 (BaseHTTPRequestHandler API)
            try:
                parsed = urlparse(self.path)
                path = parsed.path.rstrip("/") or "/"
                parsed_query = parsed.query
                if not path.startswith("/v1"):
                    self._send_error(404, f"无此路径: {path}")
                    return
                # 凭证状态回执消费（单条与批量）及凭证状态回执消费同步
                # 进度回执消费协议：显式空 X-Tenant-ID 一律 400 且仅
                # {"error": "请求非法"}（区别于其余入口的
                # “X-Tenant-ID 不能为空”）。
                if (
                    path
                    in (
                        "/v1/trust/credential-status/receipt/consume",
                        "/v1/trust/credential-status/receipt/consume-batch",

        "/v1/trust/credential-status/receipt-sync"
        "/receipt/consume",
        "/v1/trust/credential-status/receipt-sync"
        "/receipt/consume-batch",
        "/v1/trust/credentials/imported/verify-batch",
        "/v1/audit/manifest/verify-batch",
    )
    and self.headers.get("X-Tenant-ID") == ""
):
    raise ValidationError("请求非法")
tenant = self._tenant_id()
if path == "/v1/dids":
    self._post_dids(tenant)
elif path == "/v1/dids/rotation-proofs/verify":
    self._post_rotation_proofs_verify(tenant)
elif path == "/v1/audit/manifest/verify":
    self._post_audit_manifest_verify(tenant)
elif path == "/v1/audit/manifest/verify-batch":
    self._post_audit_manifest_verify_batch(tenant)
elif path == "/v1/credentials":
    self._post_credentials(tenant)
elif path == "/v1/credential-schemas":
    self._post_credential_schemas(tenant)
elif path.startswith("/v1/credential-schemas/") and path.endswith(
    "/status"
):
    self._post_credential_schema_status(
        tenant,
        path[
            len("/v1/credential-schemas/") : -len("/status")
        ],
    )
elif path == "/v1/credentials/status-export":
    self._post_credentials_status_export(tenant)
elif path == "/v1/credentials/revoke-batch":
    self._post_revoke_credentials_batch(tenant)
elif path.startswith("/v1/dids/") and path.endswith(
    "/keys/rotate"
):
    did = unquote(
        path[len("/v1/dids/") : -len("/keys/rotate")]
    )
    self._post_rotate_key(tenant, did)
elif path.startswith("/v1/dids/") and "/keys/" in path and path.endswith(
    "/revoke"
):
    middle = path[len("/v1/dids/") : -len("/revoke")]
    did_raw, sep, version_raw = middle.partition("/keys/")
    did = unquote(did_raw)
    key_version = unquote(version_raw) if sep else ""
    self._post_revoke_key(tenant, did, key_version)
elif path.startswith("/v1/dids/") and path.endswith(
    "/deactivate"
):
    did = unquote(
        path[len("/v1/dids/") : -len("/deactivate")]
    )
    self._post_deactivate_did(tenant, did)
elif path.startswith("/v1/credentials/") and path.endswith(
    "/revoke"
):
    credential_id = unquote(
        path[len("/v1/credentials/") : -len("/revoke")]
    )
    self._post_revoke_credential(tenant, credential_id)
elif path.startswith("/v1/credentials/") and path.endswith(
    "/verify"
):
    credential_id = unquote(
        path[len("/v1/credentials/") : -len("/verify")]
    )
    self._post_verify_credential(
        tenant, credential_id
    )
elif path.startswith("/v1/credentials/") and path.endswith(
    "/present"
):
    credential_id = unquote(
        path[len("/v1/credentials/") : -len("/present")]
    )
    self._post_present(tenant, credential_id)
elif path.startswith("/v1/credentials/") and path.endswith(
    "/present-batch"
):
    credential_id = unquote(
        path[len("/v1/credentials/") : -len("/present-batch")]
    )
    self._post_present_batch(tenant, credential_id)
elif path.startswith("/v1/credentials/") and path.endswith(
    "/prove"
):
    credential_id = unquote(
        path[len("/v1/credentials/") : -len("/prove")]
    )
    self._post_prove(tenant, credential_id)
elif path.startswith("/v1/credentials/") and path.endswith(
    "/prove-batch"
):
    credential_id = unquote(
        path[len("/v1/credentials/") : -len("/prove-batch")]
    )
    self._post_prove_batch(tenant, credential_id)
elif path.startswith("/v1/proofs/") and path.endswith(
    "/verify"
):
    proof_id = unquote(
        path[len("/v1/proofs/") : -len("/verify")]
    )
    self._post_verify_proof(tenant, proof_id)
elif path == "/v1/presentation-requests":
    self._post_presentation_request(tenant)
elif path.startswith("/v1/presentation-requests/") and (
